cmd:
set -e
cd /root/Iryna_Karmazina && git fetch -q origin claude/direct-automation-expeditor-671esy
cp /root/unitex-os-www/index.html /root/unitex-os-www/index.html.bak-sort
python3 - <<'EOF'
p='/root/unitex-os-www/index.html'; s=open(p,encoding='utf-8').read()
old_sort='''  // хронологія за ETA: доставлені лишаються вище, таблиця сама відкривається на угодах у роботі
  const _eta = r => { const m=/(\\d{4})-(\\d{2})-(\\d{2})/.exec(String(r["ETA"]||"")); return m? (m[1]+m[2]+m[3]) : "99999999"; };
  const _done = r => r["Статус"] === "Вантаж доставлено";
  all.sort((a,b)=> _eta(a).localeCompare(_eta(b)) || (parseInt(a["Угода"])||0) - (parseInt(b["Угода"])||0));'''
new_sort='''  // Порядок згори вниз: доставлені (за шапкою, не видно) → без ETA → найпізніші ETA →
  // ... → найближчі ETA в самому кінці. Таблиця відкривається прокрученою в кінець,
  // тому одразу видно найближчі прибуття.
  const _eta = r => { const m=/(\\d{4})-(\\d{2})-(\\d{2})/.exec(String(r["ETA"]||"")); return m? (m[1]+m[2]+m[3]) : ""; };
  const _done = r => r["Статус"] === "Вантаж доставлено";
  const _rank = r => _done(r) ? 0 : (_eta(r) ? 2 : 1);   // доставлені → без ETA → з ETA
  all.sort((a,b)=>{
    const ra=_rank(a), rb=_rank(b);
    if (ra!==rb) return ra-rb;
    if (ra===2) return _eta(b).localeCompare(_eta(a))       // найпізніші вище, найближчі внизу
      || (parseInt(a["Угода"])||0)-(parseInt(b["Угода"])||0);
    return _eta(a).localeCompare(_eta(b)) || (parseInt(a["Угода"])||0)-(parseInt(b["Угода"])||0);
  });'''
old_scroll='''    // таблиця відкривається на першій угоді в роботі (доставлені лишаються вище, за шапкою)
    const box = $("dscroll");
    if (box){
      const firstOpen = $("drows").querySelector("tr:not(.done)");
      box.scrollTop = firstOpen ? Math.max(0, firstOpen.offsetTop - 2) : 0;
    }'''
new_scroll='''    // таблиця відкривається в кінці списку — там найближчі ETA; доставлені лишаються вище, за шапкою
    const box = $("dscroll");
    if (box){
      const rows = $("drows").querySelectorAll("tr[data-id]");
      const firstOpen = $("drows").querySelector("tr:not(.done)");
      box.scrollTop = rows.length
        ? Math.max(0, box.scrollHeight - box.clientHeight)
        : (firstOpen ? Math.max(0, firstOpen.offsetTop - 2) : 0);
    }'''
done=0
for o,n in ((old_sort,new_sort),(old_scroll,new_scroll)):
    if n in s: done+=1; continue
    assert o in s, "не знайдено блок: "+o.splitlines()[0][:60]
    s=s.replace(o,n,1); done+=1
open(p,'w',encoding='utf-8').write(s); print("PATCHED_BLOCKS",done)
EOF
echo "LIVE_MD5: $(md5sum /root/unitex-os-www/index.html | cut -d' ' -f1)"
echo "REPO_MD5: $(git show origin/claude/direct-automation-expeditor-671esy:www/index.html | md5sum | cut -d' ' -f1)"
IP=$(curl -s -4 ifconfig.me); echo "UI $(curl -sk -o /dev/null -w '%{http_code}' https://$IP/)"
